    [0, 0, 0, 5, 0],
    [0, 5, 5, 5, 5],
    [5, 5, 0, 0, 0],
    [0, 5, 0, 0, 0]
]

height, width = 15, 5

# Get all unique connected components of 0s
edge_zero_cells = []
for i in range(height):
    for j in range(width):
        if volume[i][j] == 0:
            if i == 0 or i == height-1 or j == 0 or j == width-1:
                edge_zero_cells.append((i, j))

all_visited = set()
for start in edge_zero_cells:
    if start in all_visited:
        continue
    visited = set()
    queue = [start]
    while queue:
        ci, cj = queue.pop(0)
        if (ci, cj) not in visited:
            visited.add((ci, cj))
            all_visited.add((ci, cj))
            for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                ni, nj = ci + di, cj + dj
                if 0 <= ni < height and 0 <= nj < width:
                    if volume[ni][nj] == 0 and (ni, nj) not in visited:
                        queue.append((ni, nj))

print(f"Number of 'outside' 0-component(s): {len(all_visited)}")

# Check which 0-component is which
# The edited_0s from earlier
region0 = {(0, 1), (1, 2), (2, 1), (1, 1), (0, 2)}
region1 = {(0, 4), (1, 4)}
region2 = {(4, 4), (3, 3), (3, 4), (4, 3)}
region3 = {(6, 2), (4, 0), (6, 1), (5, 1), (5, 0), (6, 0), (4, 1)}
region4 = {(7, 4), (8, 4), (9, 3), (10, 4), (6, 4), (9, 2), (8, 3), (8, 2), (11, 4), (9, 4)}
region5 = {(11, 1), (9, 0), (11, 0), (12, 0), (8, 0), (11, 2), (10, 0)}
region6 = {(13, 4), (14, 4), (13, 3), (14, 3), (13, 2), (14, 2)}
region7 = {(14, 0)}

regions = [region0, region1, region2, region3, region4, region5, region6, region7]
region_names = [0, 1, 2, 3, 4, 5, 6, 7]

print("\nRegion analysis:")
for idx, region in enumerate(regions):
    inside = region - all_visited
    outside = region.intersection(all_visited)
    print(f"Region {idx}: {len(region)} cells, {len(outside)} outside, {len(inside)} inside")
    if inside:
        print(f"       inside: {sorted(inside)}")

