volume = [
    [5, 0, 0, 5, 0],
    [5, 0, 0, 5, 0],
    [5, 0, 5, 5, 5],
    [5, 5, 5, 0, 0],
    [0, 0, 5, 0, 0],
    [0, 0, 5, 5, 5],
    [0, 0, 0, 5, 0],
    [5, 5, 5, 5, 0],
    [0, 5, 0, 0, 0],
    [0, 5, 0, 0, 0],
    [0, 5, 5, 5, 0],
    [0, 0, 0, 5, 0],
    [0, 5, 5, 5, 5],
    [5, 5, 0, 0, 0],
    [0, 5, 0, 0, 0]
]

height, width = 15, 5

# Group 5s into connected components
visited = set()
components = []

for r in range(height):
    for c in range(width):
        if volume[r][c] == 5 and (r, c) not in visited:
            component = []
            queue = [(r, c)]
            while queue:
                curr = queue.pop(0)
                if curr not in visited:
                    visited.add(curr)
                    component.append(curr)
                    cr, cc = curr
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < height and 0 <= nc < width:
                            if volume[nr][nc] == 5 and (nr, nc) not in visited:
                                queue.append((nr, nc))
            components.append(component)

print(f"Found {len(components)} components of 5s:")
for idx, comp in enumerate(components):
    comp_set = set(comp)
    print(f"\nComponent {idx} ({len(comp)} cells):")
    rows = sorted(set(r for r, c in comp))
    cols = sorted(set(c for r, c in comp))
    print(f"      bbox: rows {rows[0]}-{rows[-1]}, cols {cols[0]}-{cols[-1]}")
    print(f"      Cells: {sorted(comp)}")

# Now check which regions of 0s are INSIDE each component
# A region is "inside" a component if it's completely surrounded by it

def region_inside_component(region, component_set):
    # BFS from region to see if we can escape the component
    visited = set(region)
    queue = list(region)

    # Try to reach a boundary 0 (a 0 not adjacent to any 5 in the component)
    for _ in range(len(visited) * 2):  # limit iterations
        if not queue:
            break
        cr, cc = queue.pop(0)
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < height and 0 <= nc < width:
                if volume[nr][nc] == 0 and (nr, nc) not in visited:
                    # Check if this new 0 is adjacent to a 5 in the component
                    is_adj_to_comp = False
                    for ddr, ddc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nnr, nnc = nr + ddr, nc + ddc
                        if 0 <= nnr < height and 0 <= nnc < width:
                            if volume[nnr][nnc] == 5 and (nnr, nnc) in component_set:
                                is_adj_to_comp = True
                                break
                    if not is_adj_to_comp:
                        # This 0 is adjacent to nothing (or just to non-component 5s)
                        # So we escaped!
                        return False
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    # Region is fully surrounded
    return True

# The 8-consistent regions of 0s
region0 = {(0, 1), (1, 2), (2, 1), (1, 1), (0, 2)}
region1 = {(0, 4), (1, 4)}
region2 = {(4, 4), (3, 3), (3, 4), (4, 3)}
region3 = {(6, 2), (4, 0), (6, 1), (5, 1), (5, 0), (6, 0), (4, 1)}
region4 = {(7, 4), (8, 4), (9, 3), (10, 4), (6, 4), (9, 2), (8, 3), (8, 2), (11, 4), (9, 4)}
region5 = {(11, 1), (9, 0), (11, 0), (12, 0), (8, 0), (11, 2), (10, 0)}
region6 = {(13, 4), (14, 4), (13, 3), (14, 3), (13, 2), (14, 2)}
region7 = {(14, 0)}

all_regions = [region0, region1, region2, region3, region4, region5, region6, region7]
region_names = [0, 1, 2, 3, 4, 5, 6, 7]

print("\nWhich regions are inside each 5-component?")
for comp_idx in range(len(components)):
    print(f"\nComponent {comp_idx}:")
    for region_idx, region in enumerate(all_regions):
        inside = region_inside_component(region, set(components[comp_idx]))
        if inside:
            print(f"  Region {region_names[region_idx]} ({len(region)} cells) is INSIDE this component")
